{
  "originalFormula": "L_{D} = \sqrt{ \frac{kT}{e} } \frac{1}{n_{e}}",
  "genericFormula": "L_{D} = \sqrt{ \frac{kT}{e} } \frac{1}{n_{e}}",
  "description": "Esta fórmula representa o comprimento de Debye, que é uma medida da distância sobre a qual as cargas elétricas se influenciam em um material semicondutor. O comprimento de Debye é importante para entender como as cargas se distribuem em um semicondutor e como elas afetam as propriedades elétricas do material.",
  "concepts": [
    "Comprimento de Debye",
    "Temperatura",
    "Constante de Boltzmann",
    "Carga elementar",
    "Densidade de portadores de carga"
  ],
  "symbols": [
    {
      "symbol": "L_{D}",
      "description": "Representa o comprimento de Debye, que indica a distância em que as interações eletrostáticas são significativas em um material."
    },
    {
      "symbol": "k",
      "description": "É a constante de Boltzmann, que relaciona a temperatura com a energia em sistemas físicos."
    },
    {
      "symbol": "T",
      "description": "Representa a temperatura absoluta do sistema, medida em Kelvin, que influencia a energia térmica das partículas."
    },
    {
      "symbol": "e",
      "description": "É a carga elementar, que é a menor unidade de carga elétrica, representando a carga de um único elétron."
    },
    {
      "symbol": "n_{e}",
      "description": "Representa a densidade de portadores de carga, especificamente a densidade de elétrons em um semicondutor."
    }
  ]
}

standaloneFormulas.rawText:
{
  "originalFormula": "|Q_{s}| = |Q_{b}| + |\Delta Q_{b}| = e_{n}WLx_{tr} \\left(1 + \\frac{\\xi_{xtr}}{W}\\right)",
  "genericFormula": "|Q_{s}| = |Q_{b}| + |\\Delta Q_{b}| = e_{n}WLx_{tr} \\left(1 + \\frac{\\xi_{xtr}}{W}\\right)",
  "description": "Esta fórmula representa a relação entre a carga superficial, a carga de fundo e a variação da carga de fundo em um sistema semicondutor. Ela mostra como a carga superficial é influenciada pela carga de fundo e por uma variação adicional relacionada a parâmetros físicos do material.",
  "concepts": [
    "Carga elétrica",
    "Semicondutores",
    "Propriedades elétricas dos materiais",
    "Geometria do dispositivo semicondutor"
  ],
  "symbols": [
    {
      "symbol": "Q_{s}",
      "description": "Representa a carga superficial, que é a carga elétrica acumulada na superfície de um material semicondutor."
    },
    {
      "symbol": "Q_{b}",
      "description": "Representa a carga de fundo, que é a carga elétrica presente no interior do material semicondutor."
    },
    {
      "symbol": "ΔQ_{b}",
      "description": "Representa a variação da carga de fundo, que é a mudança na quantidade de carga elétrica no interior do material semicondutor."
    },
    {
      "symbol": "e_{n}",
      "description": "Representa a permissividade elétrica do material, que é uma medida de como o material responde a um campo elétrico."
    },
    {
      "symbol": "W",
      "description": "Representa a largura do dispositivo semicondutor, que é uma dimensão física importante que afeta as propriedades elétricas."
    },
    {
      "symbol": "L",
      "description": "Representa o comprimento do dispositivo semicondutor, que também influencia as características elétricas do sistema."
    },
    {
      "symbol": "x_{tr}",
      "description": "Representa a posição de transição ou a distância a partir de um ponto de referência no dispositivo semicondutor onde ocorrem mudanças nas propriedades elétricas."
    },
    {
      "symbol": "ξ_{xtr}",
      "description": "Representa um parâmetro que pode ser relacionado a variações ou perturbações no sistema, influenciando a carga elétrica."
    }
  ]
}
